<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import type { PaperRecord, PaperTemplateRecord, QuestionRecord, QuestionType, TemplateSummary } from '../../electron/types'
import { generatePaperPlan, type PaperPlan } from '../../electron/paper-plan'
import { DEFAULT_TEMPLATE_ID } from '../../electron/default-template'
import { questionTypes } from '../../electron/paper-documents'
import { musicCategories } from '../../electron/music-categories'
import { listTemplates, importTemplate, archiveTemplate } from '../papers/template-store'
import ExamDocuments from './ExamDocuments.vue'
const props=defineProps<{questions:QuestionRecord[];papers:PaperRecord[];mode:string}>()
const emit=defineEmits<{'update:papers':[papers:PaperRecord[]];'start-exam':[paper:PaperRecord]}>()
const tab=ref('已保存试卷'),templates=ref<PaperTemplateRecord[]>([]),busy=ref(false),error=ref(''),status=ref(''),upload=ref<HTMLInputElement|null>(null)
const draft=ref<PaperRecord|null>(null),documentPaper=ref<PaperRecord|null>(null),documentSummary=ref<TemplateSummary|null>(null)
const desktop=Boolean(window.musicBank)
const year=new Date().getFullYear()
const config=reactive<PaperPlan>({name:'音乐学科期末检测试卷',grade:'全部年级',category:'全部分类',audioMode:'不限',duration:40,totalScore:100,seed:'',templateId:'',examInfo:{school:'',schoolYear:`${year}—${year+1}学年`,term:'第一学期',subject:'音乐',examDate:'',instructions:'请认真审题，独立完成作答。听音题由监考教师统一播放材料。'},rules:{'选择题':{count:10,score:3},'填空题':{count:10,score:3},'判断题':{count:10,score:2},'简答题':{count:2,score:10}}})
watch(()=>props.mode,mode=>{tab.value=mode==='随机组卷'?'生成试卷':mode==='试卷模板'?'试卷模板':'已保存试卷'},{immediate:true})
const selectedTemplate=computed(()=>templates.value.find(t=>t.id===config.templateId))
const configuredTotal=computed(()=>Object.values(config.rules).reduce((sum,rule)=>sum+Number(rule.count||0)*Number(rule.score||0),0))
const configuredCount=computed(()=>Object.values(config.rules).reduce((sum,rule)=>sum+Number(rule.count||0),0))
const pool=computed(()=>props.questions.filter(q=>q.status==='已发布'&&(config.grade==='全部年级'||q.grade===config.grade)&&(config.category==='全部分类'||q.category===config.category)&&(config.audioMode==='不限'||(config.audioMode==='仅含音频'?q.hasAudio:!q.hasAudio))))
const count=(type:QuestionType)=>pool.value.filter(q=>q.type===type).length
async function refresh(){templates.value=await listTemplates();if(!selectedTemplate.value)config.templateId=templates.value[0]?.id||''}
onMounted(()=>refresh().catch(e=>error.value=e.message))
async function imported(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;error.value='';status.value='';try{const record=await importTemplate(file);await refresh();config.templateId=record.id;status.value='模板已保存，可以用于生成试卷'}catch(e){error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
async function removeTemplate(record:PaperTemplateRecord){if(!confirm(`从可选模板中移除“${record.name}”？已保存试卷仍可使用此模板导出。`))return;busy.value=true;error.value='';try{await archiveTemplate(record.id);await refresh();status.value='模板已移除，已保存试卷不受影响'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function generate(){error.value='';status.value='';try{if(!selectedTemplate.value)throw new Error('请先上传并选择 Word 试卷模板');draft.value=generatePaperPlan(config,props.questions,selectedTemplate.value.summary);status.value='试卷已生成，题目和分值已固定为快照'}catch(e){error.value=(e as Error).message}}
function fillAvailable(){for(const type of questionTypes)config.rules[type].count=selectedTemplate.value&&!selectedTemplate.value.summary.sectionOrder.includes(type)?0:count(type);config.totalScore=configuredTotal.value}
async function save(paper:PaperRecord){
  const plain:PaperRecord=JSON.parse(JSON.stringify(paper))
  if(window.musicBank)await window.musicBank.papers.save(plain)
  else localStorage.setItem(`musicbank.paper.${paper.id}`,JSON.stringify(paper))
  emit('update:papers',[JSON.parse(JSON.stringify(paper)),...props.papers.filter(p=>p.id!==paper.id)])
}
async function saveDraft(){if(!draft.value||busy.value)return;busy.value=true;error.value='';try{await save(draft.value);status.value='试卷已保存'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function documents(paper:PaperRecord){if(busy.value)return;busy.value=true;error.value='';try{
  if(!paper.templateId){if(!selectedTemplate.value)throw new Error('请先上传模板，在组卷页选择模板后再导出');paper={...paper,templateId:selectedTemplate.value.id,templateSummary:JSON.parse(JSON.stringify(selectedTemplate.value.summary)),examInfo:{...config.examInfo}}}
  await save(paper)
  documentSummary.value=templates.value.find(t=>t.id===paper.templateId)?.summary||{sectionOrder:questionTypes,mode:'sections',pageWidth:210,pageHeight:297,warnings:[]}
  // Archived templates retain their original page geometry in the saved paper metadata.
  if(paper.templateSummary)documentSummary.value=paper.templateSummary
  documentPaper.value=JSON.parse(JSON.stringify(paper))
}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const pendingDelete=ref<PaperRecord|null>(null),deletePassword=ref('')
function deletePaper(paper:PaperRecord){pendingDelete.value=paper;deletePassword.value='';error.value=''}
async function confirmDelete(){
  const paper=pendingDelete.value;if(!paper||busy.value)return
  busy.value=true;error.value=''
  try{
    if(window.musicBank&&!await window.musicBank.system.verifyPassword(deletePassword.value))throw new Error('密码不正确，已取消删除')
    if(window.musicBank)await window.musicBank.papers.delete(paper.id);else localStorage.removeItem(`musicbank.paper.${paper.id}`)
    emit('update:papers',props.papers.filter(p=>p.id!==paper.id));if(draft.value?.id===paper.id)draft.value=null
    pendingDelete.value=null;deletePassword.value='';status.value='试卷已删除'
  }catch(e){error.value=(e as Error).message}finally{busy.value=false}
}

function load(paper:PaperRecord){draft.value=JSON.parse(JSON.stringify(paper));tab.value='生成试卷';status.value='已载入试卷快照，下方可导出或开始考试'}
</script>
<template>
<section class="view paper-workspace">
  <div class="view-heading"><div><div class="eyebrow">题库管理 / 考试试卷</div><h1>{{ tab==='试卷模板'?'试卷模板':tab==='生成试卷'?'生成考试试卷':'试卷管理' }}</h1><p>从真实 Word 模板生成试卷，分别保存试题与答案。</p></div><button v-if="tab==='试卷模板'" class="primary-button" :disabled="busy" @click="upload?.click()">＋ 上传 Word 模板</button><button v-else class="primary-button" :disabled="busy" @click="tab='生成试卷'">＋ 新建试卷</button></div>
  <div class="paper-workspace-tabs" role="tablist" aria-label="试卷工作区"><button v-for="name in ['已保存试卷','生成试卷','试卷模板']" :key="name" role="tab" :aria-selected="tab===name" @click="tab=name;error=''">{{ name }}<span v-if="name==='已保存试卷'">{{ papers.length }}</span><span v-if="name==='试卷模板'">{{ templates.length }}</span></button></div>
  <input ref="upload" type="file" accept=".docx" aria-label="上传试卷模板" class="hidden-file-input" @change="imported" />
  <div v-if="error" role="alert" class="form-error">{{ error }}</div><p v-if="status" role="status" class="paper-workspace-status">{{ status }}</p>
  <template v-if="tab==='试卷模板'">
    <div class="template-guide"><span class="template-file-icon">W</span><div><h2>把熟悉的试卷版式带进来</h2><p>上传 .docx 模板，保留纸张、标题、页眉页脚与题型顺序。每种题型使用“一、选择题”等独立标题，系统会替换标题之间的示例内容。</p><p>也可以单独一段填写 <code v-pre>{{试题}}</code>，自动插入全部题型。</p></div></div>
    <div v-if="templates.length" class="template-grid"><article v-for="item in templates" :key="item.id" class="template-card"><div class="template-card-top"><span class="template-file-icon small">W</span><span>{{ (item.fileSize/1024).toFixed(0) }} KB · Word</span></div><h3>{{ item.name }}{{ item.id === DEFAULT_TEMPLATE_ID ? ' · 系统默认' : '' }}</h3><p>{{ item.summary.sectionOrder.join(' · ') }}</p><small>{{ item.summary.pageWidth.toFixed(0) }} × {{ item.summary.pageHeight.toFixed(0) }} mm · {{ new Date(item.importedAt).toLocaleDateString() }}</small><p v-for="warning in item.summary.warnings" :key="warning" class="template-warning">{{ warning }}</p><div class="template-card-actions"><button class="secondary-button" :disabled="busy" @click="config.templateId=item.id;tab='生成试卷'">使用此模板</button><button class="text-button" :disabled="busy" :aria-label="`移除模板 ${item.name}`" @click="removeTemplate(item)">移除模板</button></div></article></div>
    <div v-else class="paper-empty"><h2>还没有试卷模板</h2><p>上传学校现有的 Word 模板，开始制作第一份试卷。</p><button class="primary-button" :disabled="busy" @click="upload?.click()">上传 Word 模板</button></div>
    <details class="template-fields"><summary>模板可填写哪些信息？</summary><p v-pre>{{试卷名称}}　{{学校}}　{{学年}}　{{学期}}　{{学科}}　{{年级}}　{{考试日期}}　{{考试时长}}　{{总分}}　{{考试说明}}</p><p>上传空白模板即可；请勿放入真实学生信息。模板正文中的“参考答案”及其后内容会清除，由题库答案重新生成。</p></details>
  </template>
  <template v-else-if="tab==='生成试卷'">
    <div class="paper-builder"><div class="paper-config-card"><div class="form-card-heading"><div><h2>试卷基本信息</h2><p>配置题量和分值，生成后固定为独立快照。</p></div><span class="generated-id">总分 <strong :class="{invalid:Math.abs(configuredTotal-config.totalScore)>.001}">{{ configuredTotal }} / {{ config.totalScore }}</strong></span></div>
      <div class="paper-form-grid"><label class="field wide"><span>试卷模板</span><select v-model="config.templateId" aria-label="选择试卷模板"><option value="">请选择模板</option><option v-for="item in templates" :key="item.id" :value="item.id">{{ item.name }}{{ item.id === DEFAULT_TEMPLATE_ID ? ' · 系统默认' : '' }}</option></select><button v-if="!templates.length" class="text-button" @click="tab='试卷模板'">先上传 Word 模板 →</button></label><label class="field wide"><span>试卷名称</span><input v-model="config.name" maxlength="100" /></label><label class="field"><span>学校</span><input v-model="config.examInfo.school" maxlength="80" placeholder="例如：实验小学" /></label><label class="field"><span>学科</span><input v-model="config.examInfo.subject" maxlength="32" /></label><label class="field"><span>学年</span><input v-model="config.examInfo.schoolYear" maxlength="40" /></label><label class="field"><span>学期</span><select v-model="config.examInfo.term"><option>第一学期</option><option>第二学期</option></select></label><label class="field"><span>年级</span><select v-model="config.grade"><option>全部年级</option><option v-for="grade in ['一年级','二年级','三年级','四年级','五年级','六年级']" :key="grade">{{ grade }}</option></select></label><label class="field"><span>试题分类</span><select v-model="config.category"><option>全部分类</option><option v-for="name in Object.keys(musicCategories)" :key="name">{{ name }}</option></select></label><label class="field"><span>考试日期</span><input v-model="config.examInfo.examDate" type="date" /></label><label class="field"><span>考试时长（分钟）</span><input v-model.number="config.duration" type="number" min="1" max="600" step="1" /></label><label class="field"><span>目标总分</span><input v-model.number="config.totalScore" type="number" min="1" step="0.5" /></label><label class="field"><span>音频试题</span><select v-model="config.audioMode"><option>不限</option><option>仅含音频</option><option>排除音频</option></select></label><label class="field wide"><span>考试说明</span><textarea v-model="config.examInfo.instructions" rows="2" maxlength="1000"></textarea></label><label class="field wide"><span>随机种子（选填，相同种子和题库得到相同题目）</span><input v-model="config.seed" maxlength="100" placeholder="例如：2026-第一学期-A卷" /></label></div>
      <div class="paper-type-config"><div v-for="(type,index) in questionTypes" :key="type" class="paper-type-row"><div class="paper-type-name"><span class="question-type" :class="['purple','blue','green','orange'][index]">{{ type[0] }}</span><div><strong>{{ type }}</strong><small>可用 {{ count(type) }} 道<span v-if="selectedTemplate&&!selectedTemplate.summary.sectionOrder.includes(type)"> · 模板无此区域</span></small></div></div><label>题数<input v-model.number="config.rules[type].count" :aria-label="`${type}题数`" type="number" min="0" max="500" step="1" /></label><span>×</span><label>每题分值<input v-model.number="config.rules[type].score" :aria-label="`${type}每题分值`" type="number" min="0.5" max="1000" step="0.5" /></label><strong class="type-total">{{ config.rules[type].count*config.rules[type].score }} 分</strong></div></div>
      <div class="paper-actions"><button class="secondary-button" :disabled="busy" @click="fillAvailable">按可用题量填充</button><button class="primary-button" :disabled="busy||!selectedTemplate" @click="generate">生成试卷</button></div>
    </div><aside class="paper-summary"><div class="aside-card"><h3>组卷摘要</h3><div class="summary-score"><strong>{{ configuredTotal }}</strong><span>分</span></div><div class="summary-row"><span>题目总数</span><b>{{ configuredCount }} 道</b></div><div class="summary-row"><span>考试时长</span><b>{{ config.duration }} 分钟</b></div><div class="summary-row"><span>可用试题</span><b>{{ pool.length }} 道</b></div></div><div class="aside-card"><h3>一份试卷，两份文档</h3><p class="workspace-tip">学生试卷保留作答空间。参考答案单独导出，包含正确答案、分值和题目解析。</p><p class="workspace-tip">听音题会标注播放材料，纸质试卷不嵌入音频。</p></div></aside></div>
    <div v-if="draft" class="generated-paper"><div class="generated-paper-heading"><div><h2>{{ draft.name }}</h2><p>{{ draft.grade }} · {{ draft.items.length }} 道题 · {{ draft.totalScore }} 分 · {{ draft.durationMinutes }} 分钟</p></div><span class="status-pill published">已生成快照</span></div><div class="generated-paper-list"><div v-for="item in draft.items" :key="item.position" class="generated-paper-item"><span class="paper-order">{{ item.position }}</span><div class="generated-copy"><strong>{{ item.snapshot.title }}</strong><span>{{ item.snapshot.type }} · {{ item.score }} 分</span></div></div></div><div class="generated-footer"><span>后续修改上方参数，需要重新生成才能应用。</span><button class="secondary-button" :disabled="busy" @click="saveDraft">保存试卷</button><button class="primary-button" :disabled="busy" @click="documents(draft)">预览与导出</button></div></div>
  </template>
  <template v-else><div v-if="papers.length" class="saved-paper-list"><article v-for="paper in papers" :key="paper.id" class="saved-paper-item"><span class="template-file-icon small">卷</span><div class="saved-paper-copy"><strong>{{ paper.name }}</strong><span>{{ paper.grade }} · {{ paper.items.length }} 道题 · {{ paper.totalScore }} 分 · {{ paper.durationMinutes }} 分钟</span><small>{{ paper.examInfo?.school }} {{ paper.examInfo?.schoolYear }}</small></div><button class="primary-button" :disabled="busy" @click="documents(paper)">预览与导出</button><button class="secondary-button" :disabled="busy" @click="emit('start-exam',paper)">开始考试</button><button class="text-button" :disabled="busy" @click="load(paper)">载入</button><button class="text-button" :disabled="busy" @click="deletePaper(paper)">删除</button></article></div><div v-else class="paper-empty"><h2>准备第一份考试试卷</h2><p>上传模板，配置题型与分值，即可生成试卷和参考答案。</p><button class="primary-button" @click="tab=templates.length?'生成试卷':'试卷模板'">{{ templates.length?'开始组卷':'上传试卷模板' }}</button></div></template>
  <Teleport to="body"><div v-if="pendingDelete" class="paper-delete-backdrop"><form class="paper-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="paper-delete-title" @submit.prevent="confirmDelete"><h2 id="paper-delete-title">删除试卷</h2><p>确定删除“{{ pendingDelete.name }}”？此操作无法撤销。</p><label v-if="desktop" class="field"><span>账户密码</span><input v-model="deletePassword" type="password" autocomplete="current-password" placeholder="输入密码确认删除" /></label><p v-if="error" role="alert" class="form-error">{{ error }}</p><div class="paper-delete-actions"><button type="button" class="secondary-button" :disabled="busy" @click="pendingDelete=null;deletePassword='';error=''">取消</button><button class="primary-button" :disabled="busy">确认删除</button></div></form></div></Teleport>
  <ExamDocuments v-if="documentPaper&&documentSummary" :paper="documentPaper" :summary="documentSummary" @close="documentPaper=null" />
</section>
</template>
<style scoped>
.paper-delete-backdrop{position:fixed;inset:0;z-index:110;background:#18253c66;backdrop-filter:blur(8px);display:grid;place-items:center}.paper-delete-dialog{width:min(420px,90vw);padding:28px;border-radius:16px;background:var(--surface);color:var(--ink);box-shadow:0 20px 80px #18253c30}.paper-delete-dialog h2{font-size:19px;margin:0 0 14px}.paper-delete-dialog p{font-size:13px;line-height:1.7}.paper-delete-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}

.paper-workspace-tabs{display:flex;gap:24px;border-bottom:1px solid var(--line);margin:0 0 26px}.paper-workspace-tabs button{padding:13px 0;color:var(--muted);font-size:13px;border-bottom:2px solid transparent;display:flex;gap:8px;align-items:center}.paper-workspace-tabs [aria-selected=true]{border-bottom-color:var(--blue);color:var(--blue);font-weight:600}.paper-workspace-tabs span{padding:2px 6px;border-radius:5px;background:var(--blue-soft);font-size:10px}.paper-workspace-status{padding:12px 16px;color:#32835c;background:#eff9f3;border-radius:10px;font-size:12px}.template-guide{display:flex;gap:20px;padding:24px;background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-bottom:22px}.template-guide h2{font-size:16px;margin:2px 0 12px}.template-guide p{font-size:12px;color:var(--muted);line-height:1.9;margin:3px 0}.template-file-icon{width:54px;height:64px;display:grid;place-items:center;background:#edf3ff;color:#4c73be;border:1px solid #dfe8f9;border-radius:8px;font-size:23px;flex-shrink:0}.template-file-icon.small{width:36px;height:44px;font-size:16px}.template-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:18px}.template-card{padding:22px;border:1px solid var(--line);border-radius:14px;background:var(--surface);display:flex;flex-direction:column}.template-card-top{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:11px}.template-card h3{font-size:15px;margin:18px 0 8px;overflow-wrap:anywhere}.template-card p{font-size:12px;color:var(--muted);line-height:1.7}.template-card small{font-size:10px;color:var(--muted)}.template-card-actions{margin-top:auto;padding-top:20px;display:flex;justify-content:space-between;gap:10px}.template-warning{color:#9b7537!important}.paper-empty{text-align:center;padding:65px 24px;border:1px dashed #dce1eb;border-radius:16px;background:var(--surface)}.paper-empty h2{font-size:19px}.paper-empty p{font-size:13px;color:var(--muted);margin-bottom:24px}.template-fields{margin-top:28px;font-size:12px;color:var(--muted);line-height:2}.template-fields summary{cursor:pointer;color:var(--ink)}.workspace-tip{font-size:12px;color:var(--muted);line-height:1.9}.field textarea{display:block;width:100%;min-width:0;line-height:1.65;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--ink);resize:vertical}.question-type.green{background:#eaf7ef;color:#48ae7d}.paper-summary h3{font-size:14px;margin-top:0}.paper-workspace button:active{transform:scale(.98)}.paper-workspace .generated-footer{flex-wrap:wrap}.paper-workspace .saved-paper-item{flex-wrap:wrap}.paper-workspace .saved-paper-copy{min-width:200px}.paper-workspace .paper-form-grid .wide{grid-column:1/-1}
</style>
